/bin/bash -lc "q='Government Science College Sikar Rajasthan'; enc="'$(python3 -c '"'import urllib.parse,sys; print(urllib.parse.quote(sys.argv[1]))' \""'$q");
for spec in "brave|https://search.brave.com/search?q=$enc" "yahoo|https://search.yahoo.com/search?p=$enc" "ecosia|https://www.ecosia.org/search?q=$enc" "startpage|https://www.startpage.com/sp/search?query=$enc"; do
  name=${spec%%|*}; url=${spec#*|}; echo "ENGINE=$name";
  out=$(mktemp "$TMPDIR/search.XXXXXX.html"); curl --insecure -L --max-time 20 -A '"'Mozilla/5.0' -sS \""'$url" -o "$out" || true;
  python3 -c '"'from bs4 import BeautifulSoup; import sys; s=BeautifulSoup(open(sys.argv[1],encoding=\"utf-8\",errors=\"ignore\"),\"html.parser\");
for a in s.select(\"a[href]\"):
 t=a.get_text(\" \",strip=True); h=a.get(\"href\",\"\");
 if t and len(t)>3 and (h.startswith(\"http\") or h.startswith(\"/\")): print(t[:160],\"|\",h[:300])' \""'$out" | grep -Ei '"'science|sikar|college|rajasthan|govt|government|http' | head -30; rm -f \""'$out"; echo '"'---';
done"

